def transform(grid):
    """Complete the outer bounding-box frame of the non-background marks."""
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    colors = [v for v in counts if v != background]
    if not colors:
        return [row[:] for row in grid]
    marker = max(colors, key=lambda v: counts[v])
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    out = [row[:] for row in grid]
    # Sparse marks describe a rectangular wiring/frame: interpolate the
    # missing cells along its four extreme straight boundary lines.
    r0, r1 = min(r for r, _ in pts), max(r for r, _ in pts)
    c0, c1 = min(c for _, c in pts), max(c for _, c in pts)
    for r in range(r0, r1 + 1):
        if grid[r][c0] == background:
            out[r][c0] = 2
        if grid[r][c1] == background:
            out[r][c1] = 2
    for c in range(c0, c1 + 1):
        if grid[r0][c] == background:
            out[r0][c] = 2
        if grid[r1][c] == background:
            out[r1][c] = 2
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))", "exit_code": 0, "error": null}

